# Look for a potential hex to char mapping for 0xc2, 0xc3 groupings
# Try grouping together sequences of these bytes for patterns
variants = [
    b'PPtN', b'PPt\xc2', b'PPt\xc2', b'PPt|', b'PPt\xc3', b'PPt6', b'PPtN', b'PPt\xc2', 
    b'PPt.', b'PPt\xc2', b'PPt\xc3', b'PPtN', b'PPt\xc3', b'PPt\xc3', b'PPt\xc2', 
    b'PPt\xc2', b'PPt\xc3', b'PPt|', b'PPt\xc2', b'PPt|', b'PPt\xc2', b'PPt\xc3', 
    b'PPt\xc3', b'PPt\xc3', b'PPt\xc3', b'PPt\xc3', b'PPt.', b'PPt\xc3', b'PPt|', 
    b'PPt\xc3', b'PPtN', b'PPtN', b'PPt.', b'PPt\xc2', b'PPt\xc3', b'PPt.', b'PPt\xc2', 
    b'PPt.'
]

# Print out sequences of 0xc2 and 0xc3 as H if c2 and C if c3, rest as themselves
pattern = ''
for v in variants:
    if v[-1] == 0xc2:
        pattern += 'H'
    elif v[-1] == 0xc3:
        pattern += 'C'
    elif v[-1] == 0x7c:
        pattern += '|'
    elif v[-1] == 0x4e:
        pattern += 'N'
    elif v[-1] == 0x36:
        pattern += '6'
    elif v[-1] == 0x2e:
        pattern += '.'
    else:
        pattern += '?'
print('Pattern using (0xc2=H, 0xc3=C, 0x7c=|, 0x4e=N, 0x2e=., 0x36=6):')
print(pattern)
